"""Camera-only integrated precinct/merchant review, registered overview unchanged."""
import json,hashlib
from pathlib import Path
HERE=Path(__file__).resolve().parent;CITY=HERE.parents[1]
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def main():
 out=CITY/'evidence/visual_registered_common_r5';p=out/'scene.json';d=json.loads(p.read_bytes());before={k:digest(d[k]) for k in ('surfaces','boxes','common_instances','common_assets')}
 handoff_path=CITY/'assemblies/property/registered/merchant_block011/terrain_handoff.json';handoff=json.loads(handoff_path.read_bytes());property_record=next(q for q in handoff['properties'] if q['property_id']=='M11_SHOP_COURT');approach=property_record['finite_gate_approach'];ring=approach['polygon_xz_m'];center=[sum(q[k] for q in ring)/len(ring) for k in (0,1)];floor=property_record['finished_floor_y_m']
 d['inspection_cameras'].update(clergy_compounds=dict(position_m=[465,225,-10],target_m=[230,22,-224]),abbey_compounds=dict(position_m=[-100,170,395],target_m=[-300,12,190]),merchant_east=dict(position_m=[350,115,170],target_m=[245,7,78]),merchant_west=dict(position_m=[100,90,165],target_m=[13,7,71]),merchant_human=dict(position_m=[center[0],floor+1.65,center[1]],target_m=[13,floor+1.65,71],eye_height_m=1.65,source_route=approach['id'],source_handoff_sha256=hashlib.sha256(handoff_path.read_bytes()).hexdigest(),limits='Camera centered in finite reserved gate approach at source floor +1.65 m; not a character or navigation pass.'),density_close=dict(position_m=[410,73,179],target_m=[334,4,90]),reservoir_north=dict(position_m=[30,70,-480],target_m=[-30,17,-365]),south_road=dict(position_m=[235,66,640],target_m=[134,2,548]))
 d['limits']=['Shared common voxel exterior assemblies plus exact-owned sampled review terrain; remaining block land use and surface art are unfinished.','Source-defined doors and routes are not a full-city character, cart or NPC navigation pass.','The bridge has a guarded closed-world actor fixture; city-wide live registration is not integrated.','Inherited road-side seams are documented separately from the newly checked finite gate and precinct joins.']
 assert before=={k:digest(d[k]) for k in before};d['camera_review_provenance']={'parent_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'unchanged_geometry':before,'registered_overview_unchanged':True};dest=out/'camera_scene.json';assert not dest.exists();dest.write_text(json.dumps(d,separators=(',',':'))+'\n');print(hashlib.sha256(dest.read_bytes()).hexdigest())
if __name__=='__main__':main()
